''<html lang="pt-BR">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">

    <title>Ativando Plano de Assinatura</title>

    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="">
    <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&amp;display=swap"
        rel="stylesheet">

    <style>
        html,
        body,
        * {
            font-family: 'Space Grotesk', system-ui, -apple-system, sans-serif;
        }

        html,
        body {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            background: transparent;
            overflow: hidden;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* CONTAINER */
        .container {
            width: 90%;
            max-width: 420px;
            text-align: center;
            position: absolute;
            left: 50%;
            top: 50%;
            transform: translate(-50%, -50%);
        }

        /* ÁREA DO CIRCULO */
        .loader-wrapper {
            position: relative;
            width: 140px;
            height: 140px;
            margin: 0 auto 18px auto;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* CIRCULO GIRANDO */
        .loader {
            position: absolute;
            width: 300px;
            height: 300px;
            border-radius: 50%;
            border: 12px solid rgba(255, 255, 255, 0.12);
            border-top: 12px solid #ffffff;
            animation: girar 1.2s linear infinite;
        }

        /* LOGO */
        .logo {
            width: 180px;
            height: auto;
            z-index: 2;
            object-fit: contain;
        }

        /* TEXTO */
        .texto {
            color: #ffffff;
            font-size: 14px;
            font-weight: 400;
            margin: 0 0 14px 0;
            letter-spacing: 0.2px;
            opacity: 0.92;
        }

        /* BARRA */
        .barra {
            width: 100%;
            height: 6px;
            background: rgba(255, 255, 255, 0.08);
            border-radius: 999px;
            overflow: hidden;
            position: relative;
        }

        /* PROGRESSO */
        .progresso {
            width: 0%;
            height: 100%;
            border-radius: 999px;
            background: linear-gradient(90deg,
                    #6366f1 0%,
                    #8b5cf6 50%,
                    #ec4899 100%);
            background-size: 200% 100%;
            box-shadow: 0 0 12px rgba(139, 92, 246, 0.55);
            animation:
                carregar 300s linear forwards,
                brilho 4s ease-in-out infinite;
        }

        /* PORCENTAGEM */
        .porcentagem {
            color: #ffffff;
            font-size: 12px;
            font-weight: 500;
            margin-top: 10px;
            letter-spacing: 0.4px;
            opacity: 0.7;
            font-variant-numeric: tabular-nums;
        }

        @keyframes carregar {
            from {
                width: 0%;
            }

            to {
                width: 100%;
            }
        }

        @keyframes brilho {
            0% {
                background-position: 0% 50%;
            }

            100% {
                background-position: 200% 50%;
            }
        }

        /* ROTAÇÃO */
        @keyframes girar {
            0% {
                transform: rotate(0deg);
            }

            100% {
                transform: rotate(360deg);
            }
        }
    </style>
</head>

<body >

    <div class="container">

        <!-- CIRCULO CENTRAL -->
        <div class="loader-wrapper">

            <div class="loader" style="
    width: 110px !important;
    border: 5px solid transparent;
    height: 110px !important;
    animation: girar 1.2s linear infinite;
    border-top: 5px solid #fff;
"></div>

            <!-- TROQUE PELA SUA LOGO -->
            <img src="https://kzxjhxctcmualiaufkqx.supabase.co/storage/v1/object/public/joystick-logos/06c81fd9-30ee-43e2-8d91-7f2dd2ccaa2d.webp"
                class="logo" style="
    width: 55px;
    border-radius: 6px;
">

        </div>

        <div class="texto">Atualização de banco em andamento...</div>

        <div class="barra">
            <div class="progresso" style="
    background: #fff;
"></div>
        </div>

        <div class="porcentagem" id="porcentagem">4%</div>

    </div>

    <script>

        const porcentagem = document.getElementById("porcentagem");

        const duracao = 300000;
        const inicio = Date.now();

        function atualizar() {

            const tempo = Date.now() - inicio;

            const progresso = Math.min(
                (tempo / duracao) * 100,
                100
            );

            porcentagem.innerText = Math.floor(progresso) + "%";

            if (progresso < 100) {
                requestAnimationFrame(atualizar);
            } else {
                porcentagem.innerText = "Plano ativado";
            }
        }

        atualizar();

    </script>











</body>

</html>

